import React, { useState } from 'react';
import { useNavigate, Navigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';
import { AlertCircle, CreditCard, ArrowLeft, ArrowRight } from 'lucide-react';

export const CheckoutPage: React.FC = () => {
  const { cartItems, cartTotal } = useCart();
  const { isAuthenticated } = useAuth();
  const navigate = useNavigate();

  const [acknowledged, setAcknowledged] = useState(false);
  const [validationError, setValidationError] = useState<string | null>(null);

  // If cart is empty, block entry and redirect to cart
  if (cartItems.length === 0) {
    return <Navigate to="/cart" replace />;
  }

  // Guided Authentication Guard: If guest user is unauthenticated, guide them to log in / register
  if (!isAuthenticated) {
    return <Navigate to="/login" state={{ fromCheckout: true }} replace />;
  }

  const handleConfirmPurchase = (e: React.FormEvent) => {
    e.preventDefault();
    setValidationError(null);

    if (!acknowledged) {
      setValidationError('Please check the simulated purchase acknowledgment checkbox to proceed.');
      return;
    }

    // Go to simulated confirmation page
    navigate('/confirmation');
  };

  return (
    <main className="max-w-2xl mx-auto px-4 py-8 flex-1 w-full">
      <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden">
        {/* Header */}
        <div className="bg-indigo-600 px-6 py-4 text-white">
          <h1 className="text-xl font-bold flex items-center gap-2">
            <CreditCard className="h-5 w-5" />
            <span>Simulated Checkout Summary</span>
          </h1>
          <p className="text-indigo-100 text-xs mt-1">
            Review your academic purchase order before final confirmation.
          </p>
        </div>

        {/* Content */}
        <div className="p-6">
          {/* Order Summary */}
          <h2 className="text-base font-bold text-gray-900 mb-3">Order Details</h2>
          <div className="divide-y divide-gray-150 border border-gray-150 rounded-lg p-4 bg-gray-50 mb-6 max-h-60 overflow-y-auto">
            {cartItems.map((item) => (
              <div key={item.product.id} className="py-2.5 flex justify-between items-center text-sm">
                <div className="min-w-0 flex-1">
                  <p className="font-semibold text-gray-800 truncate">{item.product.name}</p>
                  <p className="text-gray-500 text-xs">
                    Qty: {item.quantity} &times; ${item.product.price.toFixed(2)}
                  </p>
                </div>
                <span className="font-bold text-gray-900 ml-4 shrink-0">
                  ${(item.product.price * item.quantity).toFixed(2)}
                </span>
              </div>
            ))}
            <div className="pt-3 flex justify-between items-center text-base font-bold text-indigo-600">
              <span>Order Total</span>
              <span>${cartTotal.toFixed(2)}</span>
            </div>
          </div>

          {/* Verification / Feedback Message */}
          {validationError && (
            <div
              className="mb-4 p-3 bg-red-50 border border-red-200 rounded-md text-sm text-red-800 flex items-center gap-2"
              role="alert"
            >
              <AlertCircle className="h-5 w-5 text-red-600 shrink-0" />
              <span>{validationError}</span>
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleConfirmPurchase} noValidate aria-label="Simulated purchase confirmation form">
            {/* Minimal Demonstration Info Field */}
            <div className="mb-6 bg-indigo-50 border border-indigo-200 rounded-lg p-4">
              <div className="flex gap-3">
                <input
                  id="acknowledge_simulation"
                  name="acknowledge_simulation"
                  type="checkbox"
                  checked={acknowledged}
                  onChange={(e) => {
                    setAcknowledged(e.target.checked);
                    if (e.target.checked) setValidationError(null);
                  }}
                  className="h-5 w-5 text-indigo-600 border-gray-300 rounded-sm focus:ring-indigo-500 shrink-0 cursor-pointer"
                />
                <label
                  htmlFor="acknowledge_simulation"
                  className="text-sm text-indigo-900 font-medium leading-relaxed select-none cursor-pointer"
                >
                  I acknowledge that this is a simulated purchase for demonstration purposes. No real transaction will be made, and no real payment data is requested.
                </label>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex flex-col sm:flex-row gap-3 items-center justify-between border-t border-gray-100 pt-6">
              <button
                type="button"
                onClick={() => navigate('/cart')}
                className="w-full sm:w-auto inline-flex items-center justify-center gap-2 text-gray-600 font-semibold py-2.5 px-4 rounded-md hover:bg-gray-50 transition-colors"
              >
                <ArrowLeft className="h-4 w-4" />
                <span>Return to Cart</span>
              </button>

              <button
                type="submit"
                className="w-full sm:w-auto inline-flex items-center justify-center gap-2 bg-indigo-600 text-white font-bold py-2.5 px-6 rounded-md hover:bg-indigo-700 transition-colors shadow-xs cursor-pointer"
                aria-label="Confirm Purchase (Simulation)"
              >
                <span>Confirm Purchase</span>
                <ArrowRight className="h-4 w-4" />
              </button>
            </div>
          </form>
        </div>
      </div>
    </main>
  );
};

import React, { useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { CheckCircle2, ArrowRight, ShieldAlert, ShoppingBag } from 'lucide-react';

export const ConfirmationPage: React.FC = () => {
  const { cartItems, cartTotal, clearCart } = useCart();

  // Keep a local copy of cart details for rendering before we clear the state!
  const [summaryItems] = React.useState([...cartItems]);
  const [summaryTotal] = React.useState(cartTotal);

  // Clear the active local shopping cart immediately upon loading the confirmation screen
  useEffect(() => {
    if (cartItems.length > 0) {
      clearCart();
    }
  }, []);

  // Safeguard: If there was no purchase (empty copy), redirect to Catalog
  if (summaryItems.length === 0) {
    return <Link to="/" className="text-indigo-600 p-8 block text-center font-bold">Return to Catalog</Link>;
  }

  return (
    <main className="max-w-2xl mx-auto px-4 py-8 flex-1 w-full">
      <div className="bg-white rounded-xl shadow-md border border-gray-150 p-6 sm:p-8 text-center">
        {/* Success Icon */}
        <div className="flex justify-center mb-4">
          <CheckCircle2 className="h-16 w-16 text-green-500 animate-bounce" />
        </div>

        {/* Title & Success feedback */}
        <h1 className="text-2xl sm:text-3xl font-extrabold text-gray-900 tracking-tight mb-2">
          Simulated Purchase Confirmed!
        </h1>
        <p className="text-gray-500 text-sm mb-6">
          Thank you for exploring this demonstration store. Your simulated order was processed successfully.
        </p>

        {/* Fictitious Gateway Warning Box */}
        <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 mb-8 text-left flex gap-3">
          <ShieldAlert className="h-5 w-5 text-amber-600 shrink-0 mt-0.5" />
          <div>
            <h2 className="text-sm font-bold text-amber-900">Academic Demonstration Notice</h2>
            <p className="text-amber-800 text-xs mt-1 leading-relaxed">
              This is a demonstration store. **No real charges have been made, and no real payment gateway was contacted.** Your shopping cart has been cleared, leaving the system in a clean state to start a new purchase journey.
            </p>
          </div>
        </div>

        {/* Purchase Summary */}
        <div className="border border-gray-150 rounded-lg p-5 text-left bg-gray-50 mb-8">
          <h2 className="text-base font-bold text-gray-900 border-b border-gray-250 pb-2 mb-3">
            Simulated Receipt
          </h2>
          <div className="divide-y divide-gray-150">
            {summaryItems.map((item) => (
              <div key={item.product.id} className="py-2.5 flex justify-between items-center text-sm">
                <span className="text-gray-700 truncate max-w-xs">{item.product.name}</span>
                <span className="text-gray-900 font-semibold shrink-0 ml-4">
                  {item.quantity} &times; ${item.product.price.toFixed(2)}
                </span>
              </div>
            ))}
            <div className="pt-3 flex justify-between items-center text-base font-extrabold text-indigo-600">
              <span>Simulated Total</span>
              <span>${summaryTotal.toFixed(2)}</span>
            </div>
          </div>
        </div>

        {/* Start New Purchase Button */}
        <div>
          <Link
            to="/"
            className="inline-flex items-center gap-2 bg-indigo-600 text-white font-bold px-6 py-3 rounded-md hover:bg-indigo-700 transition-colors shadow-sm cursor-pointer"
            aria-label="Start a new simulated purchase journey"
          >
            <ShoppingBag className="h-4 w-4" />
            <span>Start New Purchase</span>
            <ArrowRight className="h-4 w-4" />
          </Link>
        </div>
      </div>
    </main>
  );
};

